def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Define a class to manage the state of paths
    class StateSpace:
        def __init__(self, val, idx1, idx2, o1, o2):
            self.val = val
            self.idx1 = idx1
            self.idx2 = idx2
            self.o1 = o1
            self.o2 = o2

    # Initialize the state spaces for the bottom-right corner
    bottom_right_values = [{}, {}, {}]

    # Function to perform DFS for maximizing the sum of values
    def dfs(x, y, val, arr1, arr2):
        # Check if the current state has been computed
        if y not in bottom_right_values[x]:
            # Initialize the current state
            bottom_right_values[x][y] = StateSpace(val, x, y, arr1, arr2)
            # Iterate through the grid to perform DFS
            for i in range(N):
                for j in range(N):
                    if (j != y or i != x) and (0 <= i < N) and (0 <= j < N):
                        # Perform DFS recursively with updated indices and values
                        dfs(i, j, arr1 + [i], arr2 + [j], val + grid_values[i][j])
                        # Explore other paths by rotating the values
                        for a, b in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                            dfs(i + a, j + b, arr1 + [i], arr2 + [j], val + grid_values[i + a][j + b])

    # Perform DFS starting from the top-left corner
    dfs(0, 0, 0, [], [])

    # Calculate the maximum sum of the two paths
    max_sum = 0
    for state in bottom_right_values[0]:
        for state2 in bottom_right_values[N - 1]:
            if state idx1 < state2 idx2:
                max_sum = max(max_sum, state.val + state2.val)
            elif state idx1 > state2 idx2:
                max_sum = max(max_sum, state2.val + state.val)
    return max_sum

