        digits = list(isbn[:9])
        checksum = sum(int(digit)) * 10 % 11
        return checksum if checksum != 10 else 'X'

    if len(isbn) != 12 or not isbn[10].isalnum():
        return "Invalid ISBN format"

    checksum = calculate_checksum(isbn[:9])
    correct_isbn = isbn[:9] + checksum

    return "Right" if checksum == isbn[10] else correct_isbn

def verify_isbn(isbn: str) -> str:
    if not isbn:
        raise ValueError("ISBN number is required")

    isbn_parts = isbn.split('-')
    if len(isbn_parts) != 5:
        raise ValueError("Invalid format. An ISBN number should be 'x-xxx-xxxxx-x'")

    if len(isbn_parts[-1]) == 1 and isbn_parts[-1] in 'Xx':
        isbn_parts[-1] = '10' if isbn_parts[-1] == 'X' else '0'

    try:
        for i in range(0, 9):
            if isbn_parts[i].startswith('0') and i != 9:
                raise ValueError("Invalid format. Leading zeros are not allowed")

        total_sum = sum(int(digit) * (2 if i % 2 == 0 else 1) for i, digit in enumerate(isbn_parts[:-1], start=1))
        checksum = 11 - (total_sum % 11)
        if checksum == 10:
            checksum = 'X'
        elif checksum == 11:
            checksum = '0'
        isbn_parts[-1] = checksum

        return '-'.join(isbn_parts)
    except ValueError as e:
        return str(e)

def verify_isbn(isbn: str) -> str:
    digits =isbn[:-1]
    if isbn[-1] == 'X':
        digits[-1] = 10
    else:
        digits[-1] = int(isbn[-1])

    if len(digits) != 10:
        raise ValueError(f"ISBN '{isbn}' is invalid. It should be 10 digits.")

    checksum = sum(int(digit) * (10 - index) for index, digit in enumerate(digits))
    if checksum % 11 != 0:
        corrected_checksum = (11 - checksum % 11) % 11
        corrected_isbn = isbn[:-1] + str(corrected_checksum)
        return corrected_isbn
    else:
        return "Right"

