def count_passing_ways(n: int, m: int) -> int:
    num_jumps = list(range(n))
    num_jumps.reverse()

    if m % 2 == 1:
        return 0

    dp = [[0] * n for _ in range(m+1)]
    dp[0][0] = 1

    for curr_length in range(1, m+1):
        for curr_student in range(n):
            dp[curr_length][curr_student] = dp[curr_length-1][num_jumps[curr_student]] + dp[curr_length-1][(curr_student + 1) % n]

    return dp[m][0]

def count_passing_ways(n: int, m: int) -> int:
    if n == 1:
        return 1

    max_iterations = 10 ** 6
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1

    for i in range(1, n):
        dp[i][0] = dp[i-1][0]
        for j in range(1, m + 1):
            dp[i][j] = dp[i-1][j] + dp[i-1][j-1]

    return dp[n-1][m] if dp[n-1][m] <= max_iterations else -1

def count_passing_ways(n: int, m: int) -> int:
    if n < 2 or m < 1 or m > n:
        raise ValueError("Invalid input parameters")

    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1  # The starting position has 1 way to stay there

    for i in range(1, n):
        for j in range(m + 1):
            dp[i][j] = (dp[(i - 1) % n][j - 1] + dp[(i - 1) % n][j]) % 1000000007

    return dp[n - 1][m]

def count_passing_ways(n: int, m: int) -> int:
    if m == 0 and n == 1:
        return 1  # Base case: only one way to have the ball start with the same student
    elif m == 0:
        return 0   # If no passes are made, the ball stays with a student
    elif m >= n or m % 2 != 0:
        return 2       # For n students and even m passes, or odd m passes, there are only two valid sequences

    dp = [[0 for _ in range(m + 1)] for _ in range(n)]
    dp[0][0] = 1  # Base case: one way if no balls are passed and no students are moved

    for i in range(1, n):
        for j in range(1, m + 1):
            # Move the ball to the left
            dp[i][j] += dp[(i - 1) % n][j - 1]
            # Move the ball to the right
            dp[i][j] += dp[(i + 1) % n][j - 1]

    # The ball returns to the starting student after m passes
    return dp[n - 1][m]

