def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Sort items based on importance value in descending order, then by price in ascending order
    items.sort(key=lambda x: (-x[1], x[0]))

    current_price = 0
    total_importance = 0

    for price, importance in items:
        if current_price + price <= n:
            current_price += price
            total_importance += importance
        else:
            # If adding the current item overflows the budget, break the loop
            break

    return total_importance

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a matrix to store the maximum happiness values
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp matrix
    for i in range(1, m + 1):
        weight, importance = items[i - 1]
        for j in range(1, n + 1):
            if weight <= j:
                dp[i][j] = max(dp[i - 1][j], importance + dp[i - 1][j - weight])
            else:
                dp[i][j] = dp[i - 1][j]

    # Return the maximum happiness value that can be achieved
    return dp[m][n]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # If the total price or importance exceeds the budget, it's impossible to achieve the desired happiness
    if n < min(item[0] for item in items) or all(item[1] < n for item in items):
        return 0

    # dp = dp[i][j] where dp[i][j] represents the maximum happiness achievable with balance i (in terms of total price) and j (in terms of importance value)
    dp = [[-1 for _ in range(n + 1)] for _ in range(m + 1)]

    # Base case: 0 importance and balance with enough price for every item
    for j in range(n, -1, -1):
        dp[0][j] = 0

    # Fill the dp table using bottom-up approach
    for i in range(1, m + 1):
        for j in range(n, -1, -1):
            # Take the current item if it's within budget
            if j >= items[i - 1][0]:
                dp[i][j] = max(dp[i - 1][j], items[i - 1][1] + dp[i - 1][j - items[i - 1][0]])
            # Skip the current item
            dp[i][j] = max(dp[i][j], dp[i - 1][j])

    return dp[m][n]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a dynamic programming table with zeros
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Iterate over the calories and the items
    for calories, importance in items:
        for weight in range(calories, n + 1):
            # If the current item can be included in the weight, update the dp table
            if calories <= weight:
                dp[m][weight] = max(importance + dp[m - 1][weight - calories], dp[m - 1][weight])

    # The result is the maximum importance value without exceeding the budget
    return dp[m][n]

def max_energy(beads):
    n = len(beads)

    # Initialize a 2D array to store the maximum energy for sub-sequences
    dp = [[0] * n for _ in range(n)]

    # Fill the dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if beads[i] == beads[j]:
                dp[i][j] = dp[i+1][j-1] + beads[i] ** 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    return dp[0][n-1]

