def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for original, encoded in zip(original, encoded):
        if original not in mapping:
            mapping[original] = encoded
        elif mapping[original] != encoded:
            return "Failed"

    decoded = [mapping.get(char, char) for char in message]

    if set(mapping.keys()) != set(decoded):
        return "Failed"

    return ''.join(decoded)

