            if j < wt:
                dp[i][j] = dp[i - 1][j]
            else:
                # Calculate the maximum value by considering the current herb or skipping it
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - wt] + val)

    # The maximum value of herbs that can be picked within the time limit is stored in dp[M][T]
    return dp[M][T]

