def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if not volumes:
        return 0  # No items to pack => minimum remaining space is 0

    if V < min(volumes):
        return V - sum(volumes)  # Insufficient capacity for all items

    dp = [0] * (V + 1)
    for volume in volumes:
