def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift(c, shift):
        base = ord('a') if c.islower() else ord('A')
        return chr((ord(c) - base + shift) % 26 + base)

    def Decrypt(ciphertext: str, key: str) -> str:
        plaintext = []
        key_index = 0
        for char in ciphertext:
            if char.isalpha():
                plaintext.append(shift(char, -shift(key[key_index]) % 26))
                key_index = (key_index + 1) % len(key)
            else:
                plaintext.append(char)
        return ''.join(plaintext)

    if not key.isalpha() or not all(c.isalpha() for c in ciphertext):
        raise ValueError("Key and ciphertext must contain only alphabetic characters.")

    return Decrypt(ciphertext, key)

def mod_inverse(a, b):
