    while a != 1:
        q = a // b
        a, b = b, a % b
        x0, x1 = x1 - q * x0, x0
        y0, y1 = y1 - q * y1, y1

    if x1 < 0:
        x1 += b

    return x1

def mod_inverse(a, b):
