        return None
    x1, x2, y1, y2 = 0, 1, 1, 0
    x, y = x2, y2
    while b > 0:
        q = a // b
        a, b = b, a % b
        x, x2 = x2 - q * x, x
        y, y2 = y2 - q * y, y
    if a != 1:
        return None
    return x % b

def mod_inverse(a, b):
    if b == 0:
        raise ValueError("Modulus must be non-zero.")
    x, y = 0, 1
    g = a % b
    while g != 0:
        q = a // b
        a, g = g, a % b
        x, y = y - q * x, x
    if a != 1:
        return None
    return x % b

