def next_permutation(perm: list) -> bool:
    # Find the first element that is smaller than the element following it from the right
    reverse_until = len(perm)
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            reverse_until = i + 1
            break
    else:
        return False

    # Find the smallest element that is larger than the element at 'reverse_until'
    for j in range(reverse_until + 1, len(perm)):
        if perm[j] > perm[reverse_until]:
            perm[reverse_until], perm[j] = perm[j], perm[reverse_until]
            break

    # Reverse the elements after 'reverse_until'
    perm[reverse_until + 1:] = perm[reverse_until + 1:][::-1]

    return True

def next_permutation(perm: list) -> bool:
    # Find the first index p such that perm[p] < perm[p+1]
    for p in range(len(perm) - 2, -1, -1):
        if perm[p] < perm[p + 1]:
            break

    # If no such index is found, the permutation is the last permutation
    if p == -1:
        return False

    # Find the smallest index q such that perm[q] > perm[p]
    for q in range(len(perm) - 1, p, -1):
        if perm[q] > perm[p]:
            break

    # Swap perm[p] and perm[q]
    perm[p], perm[q] = perm[q], perm[p]

    # Reverse the order of numbers after perm[p]
    perm[p + 1:] = perm[p + 1:][::-1]

    return True

